mapper.select:
SELECT oi.*, d.image AS dish_image, d.spice_level AS spice_level FROM order_item oi LEFT JOIN dish d ON oi.dish_id = d.id WHERE oi.order_id IN
#{id}
ORDER BY oi.order_id, oi.id

SELECT oi.dish_id AS dish_id, oi.dish_name AS dish_name, oi.price AS price, SUM(oi.quantity) AS quantity, SUM(CASE WHEN o.status = 2 THEN oi.quantity ELSE 0 END) AS consumed_quantity, SUM(CASE WHEN o.status IN (1, 4) THEN oi.quantity ELSE 0 END) AS remaining_quantity, COUNT(DISTINCT oi.order_id) AS order_count FROM order_item oi INNER JOIN `order` o ON oi.order_id = o.id WHERE o.store_id = #{storeId} AND o.date = #{date} AND o.status IN (1, 2, 4)
AND o.meal_type = #{mealType}
GROUP BY oi.dish_id, oi.dish_name, oi.price ORDER BY quantity DESC

SELECT COUNT(DISTINCT o.id)
FROM `order` o
WHERE o.store_id = #{storeId}
  AND o.date = #{date}
  AND o.status IN (1, 2, 4)

    AND o.meal_type = #{mealType}
